inputs = ['ukbxj', 'xgudju', 'efyeh', 'wzvcji', 'jduw']
outputs = ['uzkbxj', 'xgufu', 'efyeh', 'czkvcji', 'jduw']

print("Input strings:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}'")

print("\nOutput strings:")
for i, outp in enumerate(outputs):
    print(f"  {i}: '{outp}'")

print("\nDifferences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"  {i}: '{inp}' -> '{outp}'")
    else:
        print(f"  {i}: '{inp}' -> '{outp}' (unchanged)")

